if (!msg.payload || msg.payload.length === 0) return null;
msg.payload.sort((a, b) => a.timeCreated - b.timeCreated);
return msg;

const cursor_ts = msg.metadata.source.timestamp;
const utils = global.get("utils");
const connection = msg.metadata.connection_name;
const source = msg.metadata.source.identifier;

msg.payload = msg.payload.filter(entry => {
    if (entry.timeCreated <= cursor_ts) return false;
    if (entry.text && utils.is_bridge_message(entry.text)) return false;
    if (entry.loggedByFullName && utils.is_bridge_message(entry.loggedByFullName)) return false;
    return true;
});

if (msg.payload.length === 0) return null;

global.set(
    `parat_bridge.connections.${connection}.clients.${source}.timestamp`,
    msg.payload[msg.payload.length - 1].timeCreated
);

return msg;

/**
 * Extracts signed Rayvn attachment URLs from entry text.
 *
 * Signed URLs are generated when a Rayvn user right-clicks an attachment
 * and copies the link. They are publicly accessible without authentication.
 *
 * Found URLs become synthetic file objects on payload.files and are stripped
 * from text. The standard Classify files → Fetch Rayvn files pipeline then
 * downloads and forwards them to WaSOS.
 *
 * If no URLs are found, payload.files stays empty. metadata.files set by
 * Classify files (NON_TRANSFERABLE) is preserved so the notification fires.
 */
const url_pattern = /https?:\/\/\S+/gi;
const text        = msg.payload.text || "";
const matches     = [...text.matchAll(url_pattern)]
    .map(m => m[0].replace(/[.,;!?]+$/, ""))
    .filter(url => url.includes("sig="));

if (matches.length === 0) return msg;

msg.payload.files = matches.map(url => ({
    name: url.split("?")[0].split("/").pop() || "attachment",
    type: "application/octet-stream",
    size: 0,
    url
}));

let new_text = text;
for (const url of matches) {
    new_text = new_text.split(url).join("");
}
msg.payload.text = new_text.trim();

msg.metadata.files = undefined;

return msg;
